from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

TARGET = Path("src/aip/ui/shell/main_window.py")
EXPECTED_SHA256 = "01035313c804c21d5954d6157180ffe510d35cabfa8fdba204ff4a80096f360b"
PAYLOAD = ""

def main() -> int:
    data = gzip.decompress(base64.b64decode(PAYLOAD, validate=True))
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED_SHA256:
        raise RuntimeError(f"MainWindow recovery checksum mismatch: {digest}")
    TARGET.parent.mkdir(parents=True, exist_ok=True)
    TARGET.write_bytes(data)
    print(f"Restored {TARGET} sha256={digest} bytes={len(data)}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
